import { test, expect } from "playwright/test";
import { readFileSync } from "node:fs";
import { serveBuiltArtifact } from "./helpers";

/**
 * /board — board v3 ("What's coming").
 *
 * Runs against the built Pages artifact. The board's base layer is
 * the published status file (public/board-status.json, generated by
 * scripts/board/publish-status.mjs): one test below fulfils that
 * file with a renamed story and proves the board renders the file's
 * words, not anything bundled. Over the snapshot sits the live feed
 * (owner ruling, 2026-11-16): the page checks GitHub's public
 * PR/issue state and recomputes the board when — and only when —
 * every linked record is covered.
 *
 * api.github.com is ABORTED by default in this spec, so every test
 * that does not fulfil it runs the feed's honest fallback path
 * deterministically: snapshot picture, snapshot stamp, and the
 * plain note that the live check could not be completed. The live
 * tests at the bottom fulfil the API instead and prove the upgrade,
 * the coverage line, and the partial-coverage fallback. No test in
 * this file ever reaches the real GitHub.
 *
 * The player-visible baseline is locked (board cleanup, 2026-11-16):
 * 37 stories, 24 done / 4 in progress / 9 not started, exactly 8
 * bonds (the recorded waits). Every recorded wait is satisfied
 * today, so no story is waiting — the waiting behaviour is covered
 * below against a fulfilled file that re-opens one wait.
 */
test.setTimeout(180_000);

const BOARD_URL = "http://127.0.0.1:4123/Meridian/board?idle-ms=3600000";
const FRONTIER_SLUG = "pair-art-sheets-and-endings";
const WAITING_SLUG = "truce-pennant-port";
const WAITING_FOR_TITLE = "Clues arrive one at a time, one voice at a time";

test.beforeEach(async ({ context }) => {
  await serveBuiltArtifact(context);
  const shell = readFileSync("dist/client/_shell.html");
  for (const pattern of ["**/Meridian/board*", "**/Meridian/credits*", "**/Meridian/privacy*"]) {
    await context.route(pattern, async (route) => {
      if (route.request().isNavigationRequest()) {
        return route.fulfill({ status: 200, body: shell, contentType: "text/html; charset=utf-8" });
      }
      return route.fallback();
    });
  }
  await context.route("https://api.github.com/**", async (route) => route.abort());
  // Hermetic default (helpers.ts): every e2e context is served
  // flags.json with the boardLiveFeed kill switch OFF, and
  // api.github.com from seed fixtures. This spec is the feed's own
  // test, so it opts back in — the shipped flags.json verbatim —
  // while keeping the API fully stubbed per test (abort by default,
  // fulfilled payloads in the live tests). Registered last, so it
  // wins dispatch over the shared default.
  await context.route("**/flags.json*", async (route) =>
    route.fulfill({
      status: 200,
      contentType: "application/json",
      body: readFileSync("dist/client/flags.json"),
    }),
  );
});

async function openBoard(page: import("playwright/test").Page, url = BOARD_URL) {
  await page.goto(url);
  await expect(page.getByTestId("board-counts-line")).toBeVisible();
}

test("trail: snapshot picture, honestly labelled, when the live check cannot complete", async ({
  page,
}) => {
  await page.setViewportSize({ width: 1280, height: 900 });
  let githubCalled = false;
  page.on("request", (r) => {
    if (r.url().includes("api.github.com")) githubCalled = true;
  });
  await openBoard(page);

  await expect(page.getByTestId("board-counts-line")).toContainText("24 of 37 steps finished");
  await expect(page.getByTestId("board-counts-line")).toContainText("4 being built");
  await expect(page.getByTestId("board-counts-line")).toContainText("9 not started yet");
  await expect(page.getByTestId("v3-story-stop")).toHaveCount(37);

  // The live check ran — the beforeEach aborts GitHub, so it cannot
  // complete — and the board says so plainly. The snapshot stays on
  // screen under its own Updated stamp, never a liveness claim.
  await expect(page.getByTestId("board-live-note")).toBeVisible();
  await expect(page.getByTestId("board-live-note")).toContainText("live check couldn");
  const updated = await page.getByTestId("board-updated-line").innerText();
  expect(updated).toMatch(/^Updated /);
  expect(updated).not.toContain("Live from GitHub");

  // Readability law over the rendered DOM: no PR numbers, no code
  // terms, no story-id slugs as visible text.
  const bodyText = await page.locator("main").innerText();
  expect(bodyText).not.toMatch(/PR #|pull request|github/i);
  expect(bodyText).not.toMatch(/#\d{3}\b/);
  expect(bodyText.toLowerCase()).not.toMatch(/\bxp\b|\bpoints\b/);
  for (const stop of await page.getByTestId("v3-story-stop").all()) {
    const slug = await stop.getAttribute("data-slug");
    const title = await stop.locator(".v3-s-title").innerText();
    expect(title).not.toBe(slug);
    expect(title).not.toMatch(/^[a-z0-9]+(-[a-z0-9]+)+$/);
  }
  // The feed DID try — fallback honesty, not absence of the feed.
  expect(githubCalled).toBe(true);
});

