test("molecular map: bonds == recorded waits, budgets from the renderer, mirror opens the same card", async ({
  page,
}) => {
  await page.setViewportSize({ width: 1280, height: 900 });
  await openBoard(page);
  await page.getByTestId("board-nav-map").click();
  await expect(page.getByTestId("v3-you-are-here")).toContainText("All of Meridian");
  await expect(page.getByTestId("v3-mirror-story")).toHaveCount(37);

  const stage = page.getByTestId("v3-map-stage");
  await expect(stage).toHaveAttribute("data-bond-count", "8");
  const fallback = page.getByTestId("v3-webgl-fallback");
  if (await fallback.isVisible().catch(() => false)) {
    await expect(fallback).toContainText("3D needs WebGL — showing list view");
  } else {
    await expect(page.getByTestId("v3-map-canvas")).toBeVisible();
    await expect
      .poll(async () => stage.getAttribute("data-draw-calls"), { timeout: 20_000 })
      .not.toBeNull();
    const drawCalls = Number(await stage.getAttribute("data-draw-calls"));
    const triangles = Number(await stage.getAttribute("data-triangles"));
    expect(drawCalls).toBeLessThanOrEqual(80);
    expect(triangles).toBeLessThan(15_000);

    // Atom click: the stage publishes the frontier atom's projected
    // position as an e2e probe (same family as the renderer counters);
    // click exactly there — the raycast must open a story card. A
    // coarse grid search is the fallback if the probe atom is occluded.
    const box = await page.getByTestId("v3-map-canvas").boundingBox();
    expect(box).not.toBeNull();
    let opened = false;
    const probeX = await stage.getAttribute("data-probe-x");
    const probeY = await stage.getAttribute("data-probe-y");
    if (probeX && probeY) {
      await page.mouse.click(box!.x + box!.width * Number(probeX), box!.y + box!.height * Number(probeY));
      opened = await page.getByTestId("story-card-open").isVisible().catch(() => false);
    }
    outer: for (const fx of [0.3, 0.4, 0.5, 0.6, 0.7]) {
      if (opened) break;
      for (const fy of [0.3, 0.4, 0.5, 0.6, 0.7]) {
        await page.mouse.click(box!.x + box!.width * fx, box!.y + box!.height * fy);
        if (await page.getByTestId("story-card-open").isVisible().catch(() => false)) {
          opened = true;
          break outer;
        }
      }
    }
    expect(opened).toBe(true);
    // One selection, both ways: back on the trail the same card is open.
    const mapTitle = await page.getByTestId("story-card-open").locator("h4").innerText();
    await page.getByTestId("board-nav-trail").click();
    await expect(page.getByTestId("story-card-open")).toContainText(mapTitle);
  }

  // Mirror click opens the same card without any 3D at all.
  await page.getByTestId("board-nav-map").click();
  await page.locator(`[data-testid="v3-mirror-story"][data-slug="${FRONTIER_SLUG}"]`).click();
  await expect(page.getByTestId("story-card-open")).toContainText(
    "New drawings of Holmes & Watson, and how each case ends",
  );
  await expect(page.getByTestId("v3-you-are-here")).toContainText(
    "New drawings of Holmes & Watson, and how each case ends",
  );
});

