/* ------------------------------------------------------------------ */
/* Live feed (owner ruling, 2026-11-16). The GitHub API is fulfilled */
/* per test; the payloads are built from the repo's own curation +   */
/* captured record states, so they track the data as it changes.     */
/* ------------------------------------------------------------------ */

const CURATION = JSON.parse(readFileSync("src/board/curation.json", "utf8")) as {
  epics: {
    features: {
      stories: { records: number[]; tasks?: { record?: number }[] }[];
    }[];
  }[];
};
const RECORD_STATES = JSON.parse(readFileSync("src/board/record-states.json", "utf8")) as Record<
  string,
  { merged: boolean; open: boolean }
>;
const WANTED: number[] = (() => {
  const set = new Set<number>();
  for (const epic of CURATION.epics)
    for (const feature of epic.features)
      for (const story of feature.stories) {
        for (const n of story.records) set.add(n);
        for (const t of story.tasks ?? []) if (t.record !== undefined) set.add(t.record);
      }
  return [...set].sort((a, b) => a - b);
})();

const prItem = (n: number, s: { merged: boolean; open: boolean }) => ({
  number: n,
  state: s.open ? "open" : "closed",
  merged_at: s.merged ? "2026-11-01T00:00:00Z" : null,
});

/** A full pulls page 1: the given records at the given states, padded
 *  to 100 with closed+merged fillers nobody links to. */
function pullsPageOne(
  states: Map<number, { merged: boolean; open: boolean }>,
  fillerFrom = 9000,
) {
  const items = [...states.entries()].map(([n, s]) => prItem(n, s));
  for (let n = fillerFrom; items.length < 100; n++)
    items.push(prItem(n, { merged: true, open: false }));
  return items;
}

const capturedStates = (flip: Record<number, { merged: boolean; open: boolean }> = {}) =>
  new Map(
    WANTED.map(
      (n) => [n, flip[n] ?? RECORD_STATES[String(n)]] as [number, { merged: boolean; open: boolean }],
    ),
  );

const PULLS_GLOB = "https://api.github.com/repos/veeresh-bikkaneti/Meridian/pulls*";
const ISSUES_GLOB = "https://api.github.com/repos/veeresh-bikkaneti/Meridian/issues*";

test.describe("live feed", () => {
  test("a completed check upgrades the board and states its coverage", async ({ page }) => {
    await page.setViewportSize({ width: 1280, height: 900 });
    // PR 430 — the one record two finished stories hang on — is open
    // again in this payload: both stories return to In progress, the
    // counts move, and the truce flag's wait binds (Blocked).
    await page.route(PULLS_GLOB, async (route) => {
      const pageNo = Number(new URL(route.request().url()).searchParams.get("page") ?? "1");
      await route.fulfill({
        status: 200,
        contentType: "application/json",
        body: JSON.stringify(
          pageNo === 1 ? pullsPageOne(capturedStates({ 430: { merged: false, open: true } })) : [],
        ),
      });
    });
    await page.route(ISSUES_GLOB, async (route) =>
      route.fulfill({ status: 200, contentType: "application/json", body: "[]" }),
    );
    await openBoard(page);

    await expect(page.getByTestId("board-updated-line")).toContainText(
      `Live from GitHub — every linked record checked (${WANTED.length} of ${WANTED.length})`,
    );
    await expect(page.getByTestId("board-live-note")).toHaveCount(0);
    await expect(page.getByTestId("board-counts-line")).toContainText("22 of 37 steps finished");
    await expect(page.getByTestId("board-counts-line")).toContainText("6 being built");
    await expect(page.getByTestId("board-counts-line")).toContainText("9 not started yet");

    const blockedStop = page.locator(
      `[data-testid="v3-story-group"][data-group="blocked"] [data-testid="v3-story-stop"][data-slug="${WAITING_SLUG}"]`,
    );
    await expect(blockedStop).toContainText(`Waiting for: ${WAITING_FOR_TITLE}`);
    // Exactly one Blocked row renders — the waiting story's own.
    // Every other feature's Blocked group is empty, so it renders
    // no row at all (item 26).
    await expect(
      page.locator('[data-testid="v3-story-group"][data-group="blocked"]'),
    ).toHaveCount(1);
  });

  test("a check that cannot cover every record keeps the snapshot and says so", async ({
    page,
  }) => {
    await page.setViewportSize({ width: 1280, height: 900 });
    // Page 1 covers only the first 10 wanted records; page 2 is short
    // and adds none; issues are empty. Coverage 10 of 31 is not a
    // live check — the snapshot stays, labelled.
    const partial = new Map([...capturedStates()].slice(0, 10));
    await page.route(PULLS_GLOB, async (route) => {
      const pageNo = Number(new URL(route.request().url()).searchParams.get("page") ?? "1");
      await route.fulfill({
        status: 200,
        contentType: "application/json",
        body: JSON.stringify(
          pageNo === 1 ? pullsPageOne(partial) : [prItem(9100, { merged: true, open: false })],
        ),
      });
    });
    await page.route(ISSUES_GLOB, async (route) =>
      route.fulfill({ status: 200, contentType: "application/json", body: "[]" }),
    );
    await openBoard(page);

    await expect(page.getByTestId("board-live-note")).toBeVisible();
    await expect(page.getByTestId("board-counts-line")).toContainText("24 of 37 steps finished");
    const updated = await page.getByTestId("board-updated-line").innerText();
    expect(updated).toMatch(/^Updated /);
    expect(updated).not.toContain("Live from GitHub");
  });

  test("the boardLiveFeed kill switch: no GitHub call, no live wording, no note", async ({
    page,
  }) => {
    await page.setViewportSize({ width: 1280, height: 900 });
    const flags = JSON.parse(readFileSync("public/flags.json", "utf8")) as {
      flags: Record<string, boolean>;
    };
    flags.flags.boardLiveFeed = false;
    let flagsRouteHit = false;
    await page.route("**/flags.json*", async (route) => {
      flagsRouteHit = true;
      return route.fulfill({
        status: 200,
        contentType: "application/json",
        body: JSON.stringify(flags),
      });
    });
    let githubCalled = false;
    page.on("request", (r) => {
      if (r.url().includes("api.github.com")) githubCalled = true;
    });
    await openBoard(page);
    // The feed would fire within a beat of the flags landing if the
    // switch were ignored; give it that beat, then judge.
    await page.waitForTimeout(750);
    expect(flagsRouteHit, "the flags.json fulfilment must be what the app read").toBe(true);
    expect(githubCalled).toBe(false);
    await expect(page.getByTestId("board-live-note")).toHaveCount(0);
    const updated = await page.getByTestId("board-updated-line").innerText();
    expect(updated).toMatch(/^Updated /);
    expect(updated.toLowerCase()).not.toContain("live");
  });
});

test("390px: controls hide behind the Menu bar — open, Esc, outside tap, theme, view pick", async ({
  page,
}) => {
  await page.setViewportSize({ width: 390, height: 844 });
  await openBoard(page);
  const menuButton = page.getByTestId("board-menu-button");
  const trailButton = page.getByTestId("board-nav-trail");
  await expect(menuButton).toBeVisible();
  await expect(menuButton).toHaveAttribute("aria-expanded", "false");
  await expect(trailButton).toBeHidden();

  // Opening moves focus into the panel.
  await menuButton.click();
  await expect(menuButton).toHaveAttribute("aria-expanded", "true");
  await expect(trailButton).toBeVisible();
  await expect(trailButton).toBeFocused();

  // Esc closes and returns focus to the Menu button.
  await page.keyboard.press("Escape");
  await expect(menuButton).toHaveAttribute("aria-expanded", "false");
  await expect(trailButton).toBeHidden();
  await expect(menuButton).toBeFocused();

  // A tap outside the nav closes without moving the view.
  await menuButton.click();
  await expect(trailButton).toBeVisible();
  await page.locator(".v3-title").click();
  await expect(menuButton).toHaveAttribute("aria-expanded", "false");
  await expect(trailButton).toBeHidden();

  // A theme pick applies live and leaves the panel open (a setting,
  // not a navigation).
  await menuButton.click();
  await page.getByTestId("board-theme-dark").click();
  await expect(page.locator("main.board-v3")).toHaveAttribute("data-board-theme", "dark");
  await expect(menuButton).toHaveAttribute("aria-expanded", "true");

  // Picking a view navigates and closes the panel.
  await page.getByTestId("board-nav-map").click();
  await expect(page).toHaveURL(/view=map/);
  await expect(menuButton).toHaveAttribute("aria-expanded", "false");
  await expect(trailButton).toBeHidden();
});

test("v4 trail: features first, stories inside, traveller on the trail, no internal items", async ({
  page,
}) => {
  await page.setViewportSize({ width: 390, height: 844 });
  await openBoard(page);
  // The stops on the trail are the 9 player-facing features.
  await expect(page.locator(".v4-panel")).toHaveCount(9);
  await expect(page.getByTestId("board-progress-line")).toContainText("ON THE TRAIL");
  await expect(page.locator(".v4-traveller")).toBeAttached();
  // No dev language, no internal epic anywhere on the trail.
  const bodyText = await page.locator("main").innerText();
  expect(bodyText).not.toContain("Behind the Scenes");
  expect(bodyText).not.toContain("How Meridian Is Made");
  expect(bodyText).not.toContain("Subject registry");
  expect(bodyText.toLowerCase()).not.toContain("in code");
  // Stories live inside: Maths opens to its five player-words parts.
  await page.getByTestId("board-feature-toggle-maths").click();
  const maths = page.locator("#v4-stories-maths");
  await expect(maths).toContainText("Number games — counting, ordering and patterns");
  await expect(maths).toContainText("Holmes & Watson join the Maths cases");
  await expect(maths.locator('[data-testid="v3-story-stop"]')).toHaveCount(5);
});
